     8→
     9→/**
    10→ * Escape HTML entities to prevent XSS
    11→ */
    12→function escapeHtml(text: string): string {
    13→	return text
    14→		.replace(/&/g, "&amp;")
    15→		.replace(/</g, "&lt;")
    16→		.replace(/>/g, "&gt;")
    17→		.replace(/"/g, "&quot;")
    18→		.replace(/'/g, "&#39;");
    19→}
    20→
    21→/**
    22→ * Convert markdown text to HTML string with proper escaping
    23→ * @param markdown - The markdown text to convert
    24→ * @returns HTML string
